#!/usr/bin/env node
/**
 * Commit message check (the commit-msg hook): the Conventional Commits format and no
 * AI-assistant attribution. The rules are in CONTRIBUTING.md.
 *
 *   node scripts/check-commit-msg.mjs <message file>
 */
import { readFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';

export const TYPES = ['feat', 'fix', 'refactor', 'perf', 'test', 'docs', 'build', 'ci', 'chore', 'revert'];
export const MAX_HEADER = 72;

const HEADER = new RegExp(`^(${TYPES.join('|')})(\\([a-z0-9-]+(,[a-z0-9-]+)*\\))?!?: (.+)$`);
/** Headers generated by git: only checked for attribution. */
const GIT_GENERATED = /^(Merge |Revert "|fixup! |squash! |amend! )/;
const ASSISTANT_TRAILERS = [
  { pattern: /^co-authored-by:.*(claude|anthropic|copilot|chatgpt|openai|cursor)/im, what: 'an assistant Co-Authored-By' },
  { pattern: /generated (with|by) \[?(claude|chatgpt|copilot|cursor)/i, what: '"Generated with …"' },
  { pattern: /noreply@anthropic\.com/i, what: 'an Anthropic address' },
  { pattern: /^claude-session:/im, what: 'a Claude session link' },
  { pattern: /🤖/u, what: 'an assistant emoji signature' },
];

/** Message text without git comments and the part after the scissors line (git commit -v). */
export function cleanMessage(raw) {
  const lines = raw.replace(/\r\n/g, '\n').split('\n');
  const scissors = lines.findIndex((line) => /^# -+ >8 -+/.test(line));
  return (scissors === -1 ? lines : lines.slice(0, scissors))
    .filter((line) => !line.startsWith('#'))
    .join('\n')
    .trim();
}

/** List of violations; empty means the message is fine. */
export function checkMessage(raw) {
  const message = cleanMessage(raw);
  if (message === '') return []; // git rejects an empty message itself
  const errors = [];
  for (const { pattern, what } of ASSISTANT_TRAILERS) {
    if (pattern.test(message)) errors.push(`AI-assistant attribution (${what}) — the developer is the commit author, such lines are not added`);
  }
  const [header, second] = message.split('\n');
  if (GIT_GENERATED.test(header)) return errors;

  const match = HEADER.exec(header);
  if (!match) {
    errors.push(`the header does not follow "type(scope): description", types: ${TYPES.join(', ')}`);
  } else {
    const description = match[4];
    // Lowercase; an abbreviation at the start (API, IMAP) is fine.
    if (/^\p{Lu}\p{Ll}/u.test(description)) errors.push('the description starts with a lowercase letter: "add …", not "Add …"');
    if (/[.。]$/.test(description)) errors.push('no period at the end of the header');
  }
  if ([...header].length > MAX_HEADER) errors.push(`the header is longer than ${MAX_HEADER} characters (${[...header].length})`);
  if (second !== undefined && second.trim() !== '') errors.push('a blank line is required between the header and the body');
  return errors;
}

if (process.argv[1] === fileURLToPath(import.meta.url)) {
  const file = process.argv[2];
  if (!file) {
    console.error('Usage: check-commit-msg.mjs <commit message file>');
    process.exit(2);
  }
  const errors = checkMessage(readFileSync(file, 'utf8'));
  if (errors.length > 0) {
    console.error(`The commit message did not pass the check (rules: CONTRIBUTING.md):\n${errors.map((e) => `  - ${e}`).join('\n')}`);
    process.exit(1);
  }
}
